36	/* Brightness slider → 屏幕背光（PWM ch4 @40KHz，BOE 面板）+ WS2812 LED
37	 * 2026-08-08 修复：此前只调 WS2812 LED 亮度，屏幕背光不变 → "不能用"；
38	 * 现同步调屏幕背光 PWM ch4 duty（period=25000ns，polarity 与 BOE config
39	 * lcd_pwm_pol=0 一致），0-100 线性映射 duty_ns。 */
40	static void settings_brightness_cb(lv_event_t *e)
41	{
42	    lv_obj_t *slider = lv_event_get_target(e);
43	    int32_t v = lv_slider_get_value(slider);
44	    lv_obj_t *val_lbl = (lv_obj_t *)lv_obj_get_user_data(slider);
45	    if (val_lbl) {
46	        char buf[8];
47	        snprintf(buf, sizeof(buf), "%d%%", (int)v);
48	        lv_label_set_text(val_lbl, buf);
49	    }
50	    g_screen_brightness = (int)v;   /* 2026-08-23 P115：同步共享背光状态（AI 语音命令基准） */
51	#ifdef CONFIG_LUNCHER_DM_APP
52	    {
53	        struct pwm_config pcfg;
54	        memset(&pcfg, 0, sizeof(pcfg));
55	        pcfg.period_ns  = 25000;                       /* 40KHz */
56	        pcfg.duty_ns    = (uint32_t)(25000u * v / 100); /* 0-100 → 0-25000ns */
57	        pcfg.polarity   = PWM_POLARITY_NORMAL;         /* 2026-08-08 上板实测
58	                                                        * INVERSED 方向反了
59	                                                        * （100% 最暗），改
60	                                                        * NORMAL 后 100% 最亮 */
61	        hal_pwm_control(4, &pcfg);                     /* 屏幕背光 PWM ch4 */
62	    }
63	#endif
64	#ifdef CONFIG_LED_RGB_WS2812
65	    dm_led_set_brightness(v);   /* WS2812 LED，0-100 (board only) */
66	#endif
67	}
