69	/* Volume slider → 播放器音量（0-100）。
70	 * 2026-08-08 修复：此前音量滑块 cb=NULL 无任何回调 → 拖动无效（"不能用"）；
71	 * 现改 g_music_volume（dm_sound_write 下一包自动按新音量衰减），并同步
72	 * 播放器右侧音量数值（若播放器页已创建）。
73	 * Phase 1 拆分：g_music_volume / music_vol_lbl 正式定义在 deskmate_ui.c
74	 * （music 区），本文件经 deskmate_ui.h extern 引用，行为不变。 */
75	static void settings_volume_cb(lv_event_t *e)
76	{
77	    lv_obj_t *slider = lv_event_get_target(e);
78	    int32_t v = lv_slider_get_value(slider);
79	    lv_obj_t *val_lbl = (lv_obj_t *)lv_obj_get_user_data(slider);
80	    if (val_lbl) {
81	        char buf[8];
82	        snprintf(buf, sizeof(buf), "%d%%", (int)v);
83	        lv_label_set_text(val_lbl, buf);
84	    }
85	    g_music_volume = (int)v;
86	    if (music_vol_lbl)
87	        lv_label_set_text_fmt(music_vol_lbl, "%d", g_music_volume);
88	    printf("[music] settings volume=%d\n", g_music_volume);
89	}
