91	/* Auto-Lock → cycles lock timeout; persists into g_idle_timeout */
92	static const int g_autolock_secs[]  = { 30, 60, 300, 0 };      /* 0 = never */
93	static const char *g_autolock_labels[] = { "30 sec", "1 min", "5 min", "Never" };
94	static int g_autolock_idx = 0;
95	
96	static void settings_autolock_cb(lv_event_t *e)
97	{
98	    lv_obj_t *row = lv_event_get_target(e);
99	    lv_obj_t *val_lbl = (lv_obj_t *)lv_obj_get_user_data(row);
100	    if (!val_lbl) return;
101	
102	    g_autolock_idx = (g_autolock_idx + 1) % 4;
103	    lv_label_set_text(val_lbl, g_autolock_labels[g_autolock_idx]);
104	    g_idle_timeout = g_autolock_secs[g_autolock_idx];
105	    reset_idle_timer();
106	    LV_LOG_USER("Auto-Lock → %s (%ds)", g_autolock_labels[g_autolock_idx],
107	                g_idle_timeout);
108	}
