110	/* Settings → WiFi 开关（2026-08-08 接线 RTL8733BS） */
111	static void settings_wifi_cb(lv_event_t *e)
112	{
113	    lv_obj_t *sw = lv_event_get_target(e);
114	    bool on = lv_obj_has_state(sw, LV_STATE_CHECKED);
115	    /* wifijianyi.md 防狂飙：驱动操作期间禁用自身，防 1s 连点 10 次 */
116	    lv_obj_add_state(sw, LV_STATE_DISABLED);
117	    dm_net_wifi_set(on ? 1 : 0);
118	    dm_net_status_refresh();
119	    lv_obj_clear_state(sw, LV_STATE_DISABLED);
120	}
