600	/* Phase 1 拆分：show_subpage 被 ui_settings.c（WiFi/蓝牙嵌套子页入口）extern 引用 */
601	void show_subpage(const char *title)
602	{
603	    /* 2026-08-08 嵌套导航：Settings 内点 WiFi/蓝牙行开子页时，
604	     * subpage_overlay 已存在（Settings 自己）。把当前 overlay 存为
605	     * subpage_parent，新子页盖在其上；close_subpage 恢复父 overlay。
606	     * 仅允许一层嵌套：subpage_parent 已非空（已在 WiFi/蓝牙子页里）
607	     * 时拒绝第三层，同时防点击抖动双重创建。 */
608	    LV_LOG_USER("show_subpage: %s (overlay=%p parent=%p)", title, subpage_overlay, subpage_parent);
609	    if (subpage_overlay) {
610	        if (subpage_parent) {
611	            /* 已在嵌套子页内（WiFi/蓝牙页再点行）：先关闭当前子页恢复父
612	             * overlay，再重新进入同一层嵌套——实现子页间切换与重复进入
613	             * 刷新（2026-08-09 修复：原逻辑直接 return，点 WiFi/蓝牙行
614	             * 毫无响应，日志只打一行） */
615	            lv_obj_t *p = subpage_parent;
616	            close_subpage();          /* 恢复父 overlay，parent 置空 */
617	            subpage_parent = p;       /* 保持嵌套层，继续开新子页 */
618	        } else {
619	            subpage_parent = subpage_overlay;   /* 保存父（Settings） */
620	        }
621	    }
622	
623	    lv_obj_t *scr = lv_scr_act();
624	    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());
625	    lv_coord_t sh = lv_disp_get_ver_res(lv_disp_get_default());
626	
627	    /* Full-screen overlay */
628	    subpage_overlay = lv_obj_create(scr);
629	    lv_obj_set_size(subpage_overlay, sw, sh);
630	    lv_obj_set_style_bg_color(subpage_overlay, lv_color_hex(COL_BG), 0);
631	    lv_obj_set_style_bg_opa(subpage_overlay, LV_OPA_COVER, 0);
632	    lv_obj_set_style_border_width(subpage_overlay, 0, 0);
633	    lv_obj_set_style_radius(subpage_overlay, 0, 0);
634	    lv_obj_set_style_pad_all(subpage_overlay, 0, 0);
635	    lv_obj_set_scrollbar_mode(subpage_overlay, LV_SCROLLBAR_MODE_OFF);
636	    lv_obj_clear_flag(subpage_overlay, LV_OBJ_FLAG_SCROLLABLE);
637	    /* 2026-08-10 修复：scr 是 flex column 布局（ui_home.c），overlay 若
638	     * 留在 flex 流中会被布局系统重排——lv_obj_set_y(sh) 与 slide-in 动画
639	     * 全部失效（日志佐证：Open subpage done 时 overlay y=0 而非 sh），
640	     * WiFi/蓝牙嵌套子页被排到父 overlay 之后、屏幕外，表现为"点行进不去"。
641	     * FLOATING 让 overlay 脱离 flex 布局，set_y/动画恢复生效。 */
642	    lv_obj_add_flag(subpage_overlay, LV_OBJ_FLAG_FLOATING);
643	    lv_obj_move_foreground(subpage_overlay);
644	    /* Hide dock behind overlay */
645	    if (g_dock) lv_obj_add_flag(g_dock, LV_OBJ_FLAG_HIDDEN);
646	
647	    LV_LOG_USER("show_subpage: overlay created y=%d sh=%d", lv_obj_get_y(subpage_overlay), sh);
648	
649	    /* Slide-in animation from bottom */
650	    lv_obj_set_y(subpage_overlay, sh);
651	    lv_anim_t slide_in;
652	    lv_anim_init(&slide_in);
653	    lv_anim_set_var(&slide_in, subpage_overlay);
654	    lv_anim_set_exec_cb(&slide_in, (lv_anim_exec_xcb_t)lv_obj_set_y);
655	    lv_anim_set_values(&slide_in, sh, 0);
656	    lv_anim_set_time(&slide_in, 300);
657	    lv_anim_set_path_cb(&slide_in, lv_anim_path_ease_out);
658	    lv_anim_start(&slide_in);
659	
660	    /* Round back button — frosted glass, below the status bar (top-left) */
661	    lv_obj_t *back_btn = lv_btn_create(subpage_overlay);
662	    lv_obj_set_size(back_btn, DM(40), DM(40));
663	    /* 2026-08-10 修复（-23）：状态栏 132px 全宽固定顶部，返回键必须下移
664	     * 让出状态栏，禁止元素冲突（deskmate-ui skill 铁律2） */
665	    lv_obj_set_pos(back_btn, DM(16), TOP_BAR_H + DM(4));
666	    assert(DM(16) + DM(40) <= sw && TOP_BAR_H + DM(4) + DM(40) <= sh &&
667	           "deskmate: 返回键越界");
668	    lv_obj_set_style_radius(back_btn, LV_RADIUS_CIRCLE, 0);
669	    lv_obj_set_style_bg_color(back_btn, lv_color_hex(COL_CARD), 0);
670	    lv_obj_set_style_bg_opa(back_btn, LV_OPA_80, 0);
671	    lv_obj_set_style_shadow_width(back_btn, 0, 0);
672	    lv_obj_set_style_border_width(back_btn, 0, 0);
673	    lv_obj_add_event_cb(back_btn, subpage_back_cb, LV_EVENT_CLICKED, NULL);
674	
