676	    lv_label_set_text(back_icon, LV_SYMBOL_LEFT);
677	    lv_obj_set_style_text_font(back_icon, FONT_ICON, 0);
678	    lv_obj_set_style_text_color(back_icon, lv_color_hex(COL_BLUE), 0);
679	    lv_obj_center(back_icon);
680	
681	    /* ── 2026-08-10 子页状态栏：与 Home 顶部完全一致（132px 全宽）──
682	     * 复用 create_status_bar_ex（ui_home.c）：左时钟 + 中天气 +
