685	     * 指针由 clock_update_cb / weather_update_cb / dm_net_status_refresh
686	     * 每秒刷新，close_subpage 删除 overlay 前置空。 */
687	    lv_obj_t *sbar = make_clean_cont(subpage_overlay);
688	    lv_obj_set_size(sbar, lv_pct(100), TOP_BAR_H);
689	    lv_obj_set_style_bg_color(sbar, lv_color_hex(COL_CARD), 0);
690	    lv_obj_set_style_bg_opa(sbar, LV_OPA_50, 0);
691	    lv_obj_set_style_border_width(sbar, 0, 0);
692	    lv_obj_set_style_radius(sbar, 0, 0);
693	    lv_obj_align(sbar, LV_ALIGN_TOP_MID, 0, 0);
694	    create_status_bar_ex(sbar, &subpage_clock_lbl, &subpage_weather_lbl,
695	                         &subpage_wifi_lbl, &subpage_bt_lbl);
696	
697	    /* Ensure back button is on top of content */
698	    lv_obj_t *content = lv_obj_create(subpage_overlay);
699	    lv_obj_set_size(content, sw, sh);
700	    lv_obj_set_style_bg_opa(content, LV_OPA_0, 0);
701	    lv_obj_set_style_border_width(content, 0, 0);
702	    lv_obj_set_style_pad_all(content, EDGE_PAD, 0);
703	    /* 2026-08-10 修复（-22 初版/-23 完善）：状态栏 132px 全宽固定顶部，
704	     * 页面内容必须整体下移让位。初版 TOP_BAR_H+DM(10) 只避开状态栏，
705	     * 未避开下移后的返回键（底边 TOP_BAR_H+DM(44)）→ 内容仍压返回键。
706	     * 现 pad_top=TOP_BAR_H+DM(48) 同时让出状态栏与返回键，禁止元素冲突。 */
707	    lv_obj_set_style_pad_top(content, TOP_BAR_H + DM(48), 0);
708	    lv_obj_set_scrollbar_mode(content, LV_SCROLLBAR_MODE_AUTO);
709	    /* keep SCROLLABLE so long pages (Settings) can be dragged down */
710	
