781	static void temperature_observer_cb(lv_observer_t *observer, lv_subject_t *subject)
782	{
783	    LV_UNUSED(subject);
784	    lv_obj_t *label = lv_observer_get_target_obj(observer);
785	    /* 获取温度值（存储为10倍值） */
786	    int temp_value = lv_subject_get_int(&temperature_subject);
787	    int temp_integer = temp_value / 10;
788	    int temp_decimal = abs(temp_value % 10);
789	    char buf[32];
790	    /* 格式化为"23.5°C"的形式 */
791	    if (temp_value >= 0) {
792	        lv_snprintf(buf, sizeof(buf), "%d.%d°C", temp_integer, temp_decimal);
793	    } else {
794	        lv_snprintf(buf, sizeof(buf), "-%d.%d°C", -temp_integer, temp_decimal);
795	    }
796	    /* 根据温度值设置不同的颜色 */
797	    if (temp_integer < 18) {
798	        lv_obj_set_style_text_color(label, lv_color_hex(0xE74C3C), 0); // 红色，偏冷
799	    } else if (temp_integer > 28) {
800	        lv_obj_set_style_text_color(label, lv_color_hex(0xE74C3C), 0); // 红色，偏热
801	    } else {
802	        lv_obj_set_style_text_color(label, lv_color_hex(0xFFFFFF), 0); // 白色，舒适
803	    }
804	    lv_label_set_text(label, buf);
805	    LV_LOG_INFO("Temperature displayed: %s", buf);
806	}
